{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "Cilomilast has a measured mean absolute oral bioavailability of 96% (range 92–102%) in healthy humans, directly supporting high oral bioavailability for the query given its high assay-transfer score.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Tramadol shows 68% mean oral bioavailability in humans, an independent high-bioavailability measurement with strong transferability to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Ethinyl estradiol, a steroid structurally closer to the query, has oral bioavailability of about 25–65% in women; although lower than other analogues, it remains above the 20% threshold and supports a high prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "17-Methyltestosterone, another steroid, is reported to have good oral bioavailability in humans, supporting high oral bioavailability for the steroid-like query scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Estetrol, a steroid hormone, is reported to have high and dose-related oral bioavailability in humans, providing additional steroid-scaffold evidence for high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved experimental analogues, including steroid and non-steroid drugs, show oral bioavailability above the 20% threshold in humans, with the highest-transfer evidence strongly supporting a high prediction. No retrieved evidence supports low oral bioavailability for the query.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself.",
    "No intravenous comparator data are available for the query, so first-pass metabolism extent is not directly quantified.",
    "Potential effects of the 17-acetoxy-20-keto and 11β-dimethylaminophenyl substituents on presystemic clearance are inferred rather than directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

